class_name InvGrid
extends Control
## Wave 66 (inv-ui): the cell grid of the bag as a component. The inventory screen (36 cells: belt row + 3
## rows) and the workbench's bag column (big pockets of matter stacks with a piece thumbnail, a name and a
## volume) both use it. It only DRAWS Bag cells and reports hover / pick; every move stays in Bag.click /
## quick / equip / unequip (InventoryView calls them).
##
##   setup(cols, rows, cell, filter)  filter: Callable(item: Dictionary) -> bool; items it rejects are dimmed and
##                                    never emit `picked` (a head piece that cannot be a haft: dim, not hidden)
##   rect_of(loc) -> Rect2            the rectangle of Bag loc in this control's coordinates (Rect2() if not shown)
##   loc_at(p) -> int                 the Bag loc under local point p, -1 none
##   signals hovered(loc), picked(loc)  (self_input = true: this control reads the mouse itself;
##                                    false: the parent owns the mouse and sets `hover` / `selected`)
## Options: first (the first Bag loc shown), locs (an explicit list of Bag locs instead of first..first+n),
## gap, row_sep (extra gap after the first row: the belt), belt_n (cells that carry the keys​ 1..n), big
## (matter pockets: name + volume under the thumbnail), cell_h (pocket height when it differs from the width).

signal hovered(loc: int)
signal picked(loc: int)

var cols := 9
var rows := 4
var cell := 60.0
var cell_h := 0.0
var gap := 4.0
var row_sep := 10.0
var belt_n := 0
var first := 0
var locs := PackedInt32Array()
var big := false
var filter := Callable()
var self_input := true
var hover := -1:
	set(v):
		if v != hover:
			hover = v
			queue_redraw()
var selected := -1:
	set(v):
		if v != selected:
			selected = v
			queue_redraw()

static var _thumbs: Script = null
static var _thumbs_looked := false


func setup(c: int, r: int, cell_px: float, flt := Callable()) -> void:
	cols = c
	rows = r
	cell = cell_px
	filter = flt
	custom_minimum_size = needed()
	size = custom_minimum_size
	mouse_filter = Control.MOUSE_FILTER_STOP if self_input else Control.MOUSE_FILTER_IGNORE
	queue_redraw()


## The pixel size the grid needs.
func needed() -> Vector2:
	var ch := _ch()
	var extra := row_sep if (rows > 1 and row_sep > 0.0 and belt_n > 0) else 0.0
	return Vector2(cols * cell + (cols - 1) * gap, rows * ch + (rows - 1) * gap + extra)


func _ch() -> float:
	return cell_h if cell_h > 0.0 else cell


func count() -> int:
	return locs.size() if not locs.is_empty() else cols * rows


func loc_of_index(i: int) -> int:
	return locs[i] if not locs.is_empty() else first + i


func index_of(loc: int) -> int:
	if not locs.is_empty():
		return locs.find(loc)
	var i := loc - first
	return i if i >= 0 and i < cols * rows else -1


func _rect_i(i: int) -> Rect2:
	var row := i / cols
	var extra := row_sep if (row > 0 and belt_n > 0) else 0.0
	return Rect2(Vector2((i % cols) * (cell + gap), row * (_ch() + gap) + extra), Vector2(cell, _ch()))


func rect_of(loc: int) -> Rect2:
	var i := index_of(loc)
	return _rect_i(i) if i >= 0 and i < count() else Rect2()


func loc_at(p: Vector2) -> int:
	for i in count():
		if _rect_i(i).grow(gap * 0.5).has_point(p):
			return loc_of_index(i)
	return -1


## An item passes the filter (no filter: every item).
func passes(it: Dictionary) -> bool:
	return not filter.is_valid() or bool(filter.call(it))


func _gui_input(event: InputEvent) -> void:
	if not self_input:
		return
	if event is InputEventMouseMotion:
		var l := loc_at(event.position)
		if l != hover:
			hover = l
			hovered.emit(l)
	elif event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
		var l := loc_at(event.position)
		if l >= 0 and passes(Bag.get_at(l)):
